-- Isolated ExternalIntegration catalog metadata only.
WITH columns AS (SELECT (SELECT string_agg(concat_ws('|', table_name, ordinal_position, column_name, data_type, udt_name, is_nullable, coalesce(column_default,'')), E'\n' ORDER BY table_name, ordinal_position) FROM information_schema.columns WHERE table_schema='app_external_integration') AS serialized FROM pg_namespace n WHERE n.nspname='app_external_integration'),
constraints AS (SELECT (SELECT string_agg(concat_ws('|', r.relname, c.conname, c.contype, pg_get_constraintdef(c.oid,true)), E'\n' ORDER BY r.relname,c.conname) FROM pg_constraint c JOIN pg_class r ON r.oid=c.conrelid JOIN pg_namespace cn ON cn.oid=r.relnamespace WHERE cn.nspname='app_external_integration') AS serialized FROM pg_namespace n WHERE n.nspname='app_external_integration'),
indexes AS (SELECT (SELECT string_agg(concat_ws('|', it.relname, ii.relname, pg_get_indexdef(ix.indexrelid)), E'\n' ORDER BY it.relname,ii.relname) FROM pg_index ix JOIN pg_class it ON it.oid=ix.indrelid JOIN pg_class ii ON ii.oid=ix.indexrelid JOIN pg_namespace ixn ON ixn.oid=it.relnamespace WHERE ixn.nspname='app_external_integration') AS serialized FROM pg_namespace n WHERE n.nspname='app_external_integration'),
runtimeACL AS (SELECT (SELECT string_agg(concat_ws('|',r.relname,a.privilege_type,CASE WHEN a.is_grantable THEN 'YES' ELSE 'NO' END),E'\n' ORDER BY r.relname,a.privilege_type) FROM pg_class r CROSS JOIN LATERAL aclexplode(coalesce(r.relacl,acldefault('r',r.relowner))) a WHERE r.relnamespace=n.oid AND r.relkind='r' AND a.grantee=(SELECT oid FROM pg_roles WHERE rolname='ai_mls_production_runtime')) AS serialized FROM pg_namespace n WHERE n.nspname='app_external_integration'),
triggers AS (SELECT (SELECT string_agg(concat_ws('|',r.relname,tr.tgname,tr.tgenabled,tr.tgtype,pn.nspname,p.proname,pg_get_triggerdef(tr.oid,true)),E'\n' ORDER BY r.relname,tr.tgname) FROM pg_trigger tr JOIN pg_class r ON r.oid=tr.tgrelid JOIN pg_namespace tn ON tn.oid=r.relnamespace JOIN pg_proc p ON p.oid=tr.tgfoid JOIN pg_namespace pn ON pn.oid=p.pronamespace WHERE tn.nspname='app_external_integration' AND NOT tr.tgisinternal) AS serialized FROM pg_namespace n WHERE n.nspname='app_external_integration'),
functions AS (SELECT (SELECT string_agg(concat_ws('|',p.proname,l.lanname,pg_get_function_result(p.oid),trim(p.prosrc),pg_get_userbyid(p.proowner),p.prosecdef,coalesce(array_to_string(p.proconfig,','),'')),E'\n' ORDER BY p.proname) FROM pg_proc p JOIN pg_namespace fn ON fn.oid=p.pronamespace JOIN pg_language l ON l.oid=p.prolang WHERE fn.nspname='app_external_integration') AS serialized FROM pg_namespace n WHERE n.nspname='app_external_integration'),
effectiveACL AS (SELECT (SELECT string_agg(concat_ws('|',rt.tablename,has_table_privilege('ai_mls_production_runtime',format('%I.%I',rt.schemaname,rt.tablename),'SELECT'),has_table_privilege('ai_mls_production_runtime',format('%I.%I',rt.schemaname,rt.tablename),'INSERT'),has_table_privilege('ai_mls_production_runtime',format('%I.%I',rt.schemaname,rt.tablename),'UPDATE'),has_table_privilege('ai_mls_production_runtime',format('%I.%I',rt.schemaname,rt.tablename),'DELETE'),has_table_privilege('ai_mls_production_runtime',format('%I.%I',rt.schemaname,rt.tablename),'TRUNCATE'),has_table_privilege('ai_mls_production_runtime',format('%I.%I',rt.schemaname,rt.tablename),'REFERENCES'),has_table_privilege('ai_mls_production_runtime',format('%I.%I',rt.schemaname,rt.tablename),'TRIGGER')),E'\n' ORDER BY rt.tablename) FROM pg_tables rt WHERE rt.schemaname='app_external_integration') AS serialized FROM pg_namespace n WHERE n.nspname='app_external_integration'),
non_n AS (SELECT (SELECT string_agg(concat_ws('|', r.relname, c.conname, c.contype, pg_get_constraintdef(c.oid,true)), E'\n' ORDER BY r.relname,c.conname) FROM pg_constraint c JOIN pg_class r ON r.oid=c.conrelid JOIN pg_namespace cn ON cn.oid=r.relnamespace WHERE cn.nspname='app_external_integration' AND c.contype <> 'n') AS serialized FROM pg_namespace n WHERE n.nspname='app_external_integration')
SELECT current_setting('server_version') AS server_version,
 current_setting('server_version_num') AS server_version_num,
 current_setting('data_directory') AS data_directory,current_user,current_database(),current_setting('search_path') AS search_path,
 'POST_EXTERNAL_INTEGRATION_RUNTIME_GRANTS' AS capture_stage,
 (SELECT pg_get_userbyid(nspowner) FROM pg_namespace WHERE nspname='app_external_integration') AS schema_owner,
 obj_description('app_external_integration'::regnamespace,'pg_namespace') AS schema_comment,
 (SELECT jsonb_agg(tablename ORDER BY tablename) FROM pg_tables WHERE schemaname='app_external_integration') AS table_inventory,
 (SELECT count(*) FROM pg_tables WHERE schemaname='app_external_integration') AS table_count,
 current_setting('ai_mls.r3b1_external_integration_artifact_sha256',true) AS artifact_guc,
 current_setting('ai_mls.r3b1_external_integration_artifact_sha256',true) IS NOT NULL AS artifact_guc_present,
 (SELECT count(*) FROM pg_constraint c JOIN pg_class r ON r.oid=c.conrelid JOIN pg_namespace n ON n.oid=r.relnamespace WHERE n.nspname='app_external_integration') AS constraint_count,
 (SELECT jsonb_object_agg(contype,num) FROM (SELECT c.contype,count(*) AS num FROM pg_constraint c JOIN pg_class r ON r.oid=c.conrelid JOIN pg_namespace n ON n.oid=r.relnamespace WHERE n.nspname='app_external_integration' GROUP BY c.contype) counted) AS constraint_counts_by_type,
 (SELECT count(*) FROM pg_constraint c JOIN pg_class r ON r.oid=c.conrelid JOIN pg_namespace n ON n.oid=r.relnamespace WHERE n.nspname='app_external_integration' AND c.contype='n') AS not_null_constraint_count,
 (SELECT count(*) FROM pg_attribute a JOIN pg_class r ON r.oid=a.attrelid JOIN pg_namespace n ON n.oid=r.relnamespace WHERE n.nspname='app_external_integration' AND r.relkind='r' AND a.attnum>0 AND NOT a.attisdropped AND a.attnotnull) AS not_null_column_count,
 jsonb_build_object('hash',md5(non_n.serialized),'serialized',non_n.serialized) AS non_n_constraints,
 (SELECT jsonb_agg(jsonb_build_object('table',r.relname,'constraint',c.conname,'type',c.contype,'validated',c.convalidated,'definition',pg_get_constraintdef(c.oid,true)) ORDER BY r.relname,c.conname) FROM pg_constraint c JOIN pg_class r ON r.oid=c.conrelid JOIN pg_namespace n ON n.oid=r.relnamespace WHERE n.nspname='app_external_integration' AND c.contype<>'n') AS non_n_constraint_rows,
 jsonb_build_object('columns',jsonb_build_object('hash',md5(columns.serialized),'serialized',columns.serialized),'constraints',jsonb_build_object('hash',md5(constraints.serialized),'serialized',constraints.serialized),'indexes',jsonb_build_object('hash',md5(indexes.serialized),'serialized',indexes.serialized),'triggers',jsonb_build_object('hash',md5(triggers.serialized),'serialized',triggers.serialized),'functions',jsonb_build_object('hash',md5(functions.serialized),'serialized',functions.serialized),'runtimeACL',jsonb_build_object('hash',md5(runtimeACL.serialized),'serialized',runtimeACL.serialized),'effectiveACL',jsonb_build_object('hash',md5(effectiveACL.serialized),'serialized',effectiveACL.serialized)) AS components
FROM columns,constraints,indexes,triggers,functions,runtimeACL,effectiveACL,non_n;
